zaura_surface_draw_attention(struct zaura_surface *zaura_surface)
{
	wl_proxy_marshal_flags((struct wl_proxy *) zaura_surface,
			 ZAURA_SURFACE_DRAW_ATTENTION, NULL, wl_proxy_get_version((struct wl_proxy *) zaura_surface), 0);
}

