/**
 * @ingroup iface_zaura_output
 * @struct zaura_output_listener
 */
struct zaura_output_listener {
	/**
	 * advertise available scales for the output
	 *
	 * The scale event describes an available scale for the output.
	 *
	 * The event is sent when binding to the output object and there
	 * will always be one scale, the current scale. The event is sent
	 * again if an output changes scale, for the scale that is now
	 * current. In other words, the current scale is always the last
	 * scale that was received with the current flag set.
	 * @param flags bitfield of scale flags
	 * @param scale output scale
	 * @since 2
	 */
	void (*scale)(void *data,
		      struct zaura_output *zaura_output,
		      uint32_t flags,
		      uint32_t scale);
	/**
	 * advertise connection for the output
	 *
	 * The connection event describes how the output is connected.
	 *
	 * The event is sent when binding to the output object.
	 * @param connection output connection
	 * @since 5
	 */
	void (*connection)(void *data,
			   struct zaura_output *zaura_output,
			   uint32_t connection);
	/**
	 * advertise device scale factor for the output
	 *
	 * This event describes the device specific scale factor for the
	 * output.
	 *
	 * The device specific scale factor is not expected the change
	 * during the lifetime of the output. And it is not limited to an
	 * integer value like the scale factor provided by wl_output
	 * interface. The exact contents scale used by the compositor can
	 * be determined by combining this device scale factor with the
	 * current output scale.
	 *
	 * The event is sent when binding to the output object.
	 * @param scale output device scale factor
	 * @since 5
	 */
	void (*device_scale_factor)(void *data,
				    struct zaura_output *zaura_output,
				    uint32_t scale);
	/**
	 * advertise the work area insets for the output
	 *
	 * This event describes the insets for the output in logical
	 * screen coordinates, from which the work area can be calculated.
	 *
	 * This event is sent before wl_output.done, after which the client
	 * would apply the change.
	 * @since 33
	 */
	void (*insets)(void *data,
		       struct zaura_output *zaura_output,
		       int32_t top,
		       int32_t left,
		       int32_t bottom,
		       int32_t right);
	/**
	 * advertise the output's logical transform
	 *
	 * This event describes the logical transform for the output.
	 * Whereas wl_output.geometry's transform corresponds to the
	 * display's panel rotation, the logical transform corresponds to
	 * the display's logical rotation.
	 *
	 * This event is sent before wl_output.done, after which the client
	 * would apply the change.
	 * @since 34
	 */
	void (*logical_transform)(void *data,
				  struct zaura_output *zaura_output,
				  int32_t transform);
	/**
	 * advertise the output's display id
	 *
	 * This event describes the 64bit display id assigned to each
	 * display by ChromeOS. The value is opaque and should not be
	 * interpreted.
	 * @since 43
	 */
	void (*display_id)(void *data,
			   struct zaura_output *zaura_output,
			   uint32_t display_id_hi,
			   uint32_t display_id_lo);
	/**
	 * target display for new windows
	 *
	 * Notifies that this output is now active output. It is
	 * typically used as a target when a new window is created without
	 * specific bounds.
	 * @since 45
	 */
	void (*activated)(void *data,
			  struct zaura_output *zaura_output);
};

/**
 * @ingroup iface_zaura_output
 */
static inline int
zaura_output_add_listener(struct zaura_output *zaura_output,
			  const struct zaura_output_listener *listener, void *data)
{
	return wl_proxy_add_listener((struct wl_proxy *) zaura_output,
				     (void (**)(void)) listener, data);
}

