/**
 * @ingroup iface_zaura_toplevel
 * @struct zaura_toplevel_listener
 */
struct zaura_toplevel_listener {
	/**
	 * suggest a surface change
	 *
	 * A configuration change that also includes the window origin in
	 * screen coordinates.
	 * @since 29
	 */
	void (*configure)(void *data,
			  struct zaura_toplevel *zaura_toplevel,
			  int32_t x,
			  int32_t y,
			  int32_t width,
			  int32_t height,
			  struct wl_array *states);
	/**
	 * window origin change
	 *
	 * A notification sent when the window origin has changed. Unlike
	 * a configure, this does not imply the client needs to resize. The
	 * values are in screen coordinates.
	 * @since 29
	 */
	void (*origin_change)(void *data,
			      struct zaura_toplevel *zaura_toplevel,
			      int32_t x,
			      int32_t y);
	/**
	 * set the raster scale during a configure
	 *
	 * Sets the raster scale of this window. This should be called
	 * during a configure event sequence. To do so we reinterpret_cast
	 * into a 32-bit uint and later cast back into a float. This is
	 * because wayland does not support native transport of floats. As
	 * different CPU architectures may use different endian
	 * representations for IEEE 754 floats, this protocol implicitly
	 * assumes that the caller and receiver are the same machine.
	 * @param scale Raster scale, in float format
	 * @since 50
	 */
	void (*configure_raster_scale)(void *data,
				       struct zaura_toplevel *zaura_toplevel,
				       uint32_t scale);
	/**
	 * rotate focus within window
	 *
	 * Rotates focus within the toplevel window. The window must sort
	 * its focusable view into a stable and linearly traversable order.
	 * Prior to rotating focus, the surface should already be activated
	 * and have keyboard focus. If the surface has not been activated
	 * or does not have keyboard focus, the server should first
	 * activate and enter keyboard focus for the window. An example of
	 * event order could be:
	 *
	 * 1. activate surface 2. enter keyboard focus 3. rotate focus
	 *
	 * If the window is not activated or does not have keyboard focus,
	 * the client should respond with a "not handled" and not perform
	 * any operation.
	 *
	 * To start a new series rotation, the server will set the
	 * "restart" arg to true. If the "restart" arg is set to true, the
	 * window should set the focus on the first UI element for the
	 * given direction and not perform any rotation.
	 *
	 * The client should respond with whether the rotation was
	 * successful via the "handled" field in the "ack_rotate_focus"
	 * request. The client should pass on the event serial and
	 * direction within the ack message.
	 * @param serial serial for the rotation event
	 * @param direction the direction for linear traversal
	 * @param restart whether or not to restart traversal
	 * @since 56
	 */
	void (*rotate_focus)(void *data,
			     struct zaura_toplevel *zaura_toplevel,
			     uint32_t serial,
			     uint32_t direction,
			     uint32_t restart);
	/**
	 * window is in overview
	 *
	 * The window is being shown in overview mode. Note that this is
	 * different than shell overview state, as not all windows will be
	 * part of the overview grid.
	 * @param in_overview in overview or not
	 * @since 62
	 */
	void (*overview_change)(void *data,
				struct zaura_toplevel *zaura_toplevel,
				uint32_t in_overview);
};

