static inline void
zaura_popup_surface_submission_in_pixel_coordinates(struct zaura_popup *zaura_popup)
{
	wl_proxy_marshal_flags((struct wl_proxy *) zaura_popup,
			 ZAURA_POPUP_SURFACE_SUBMISSION_IN_PIXEL_COORDINATES, NULL, wl_proxy_get_version((struct wl_proxy *) zaura_popup), 0);
}

